std::optional<std::size_t> rvaoff(const PeInfo&pe,std::uint32_t rva,std::size_t n){if(rva<pe.headers_size&&rva<n)return std::size_t(rva);for(const auto&s:pe.sections){auto span=std::max(s.vsize,s.raw_size);if(rva>=s.rva&&std::uint64_t(rva)<std::uint64_t(s.rva)+span){auto delta=std::uint64_t(rva)-s.rva;if(delta>=s.raw_size)return{};auto o=std::uint64_t(s.raw_offset)+delta;if(o<n)return std::size_t(o);}}return{};}
std::optional<std::uint64_t> fileoff(const PeInfo&pe,std::uint32_t rva){for(const auto&s:pe.sections){if(rva>=s.rva&&std::uint64_t(rva)<std::uint64_t(s.rva)+s.raw_size)return std::uint64_t(s.raw_offset)+(rva-s.rva);}if(rva<pe.headers_size)return rva;return{};}
ZydisRegister large(ZydisRegister r){return r==ZYDIS_REGISTER_NONE?r:ZydisRegisterGetLargestEnclosing(ZYDIS_MACHINE_MODE_LONG_64,r);}
struct FuncRange{std::uint32_t begin=0,end=0;};
FuncRange runtime_func(const PeInfo&pe,std::uint32_t rva){for(const auto&f:pe.exception.runtime_functions)if(f.begin_rva<=rva&&rva<f.end_rva)return{f.begin_rva,f.end_rva};return{};}
bool executable_rva(const PeInfo&pe,std::uint32_t rva){for(const auto&s:pe.sections){if(!(s.characteristics&0x20000000u))continue;auto span=std::max(s.vsize,s.raw_size);if(rva>=s.rva&&std::uint64_t(rva)<std::uint64_t(s.rva)+span)return true;}return false;}
struct Decoded{std::uint32_t rva=0;ZydisDecodedInstruction zi{};std::array<ZydisDecodedOperand,ZYDIS_MAX_OPERAND_COUNT>ops{};};
std::vector<Decoded> decode_range(std::span<const std::uint8_t>d,const PeInfo&pe,FuncRange f){std::vector<Decoded>out;if(!f.end||f.end<=f.begin)return out;ZydisDecoder dec;if(!ZYAN_SUCCESS(ZydisDecoderInit(&dec,ZYDIS_MACHINE_MODE_LONG_64,ZYDIS_STACK_WIDTH_64)))return out;auto cur=f.begin;while(cur<f.end&&out.size()<8192){auto o=rvaoff(pe,cur,d.size());if(!o||*o>=d.size())break;Decoded x;x.rva=cur;auto avail=std::min<std::size_t>(d.size()-*o,f.end-cur);if(!ZYAN_SUCCESS(ZydisDecoderDecodeFull(&dec,d.data()+*o,avail,&x.zi,x.ops.data()))||!x.zi.length)break;out.push_back(x);cur+=x.zi.length;}return out;}
struct ImportedCall{std::string module,name,transfer;std::uint32_t callsite=0,func_begin=0,func_end=0,iat_rva=0;};
std::span<const std::uint8_t> raw_runtime_function(std::span<const std::uint8_t>d,const PeInfo&pe,const PeRuntimeFunction&rf){if(rf.end_rva<=rf.begin_rva)return{};auto b=rvaoff(pe,rf.begin_rva,d.size()),e=rvaoff(pe,rf.end_rva-1,d.size());if(!b||!e||*e<*b||*e-*b+1!=rf.end_rva-rf.begin_rva)return{};return d.subspan(*b,*e-*b+1);}
bool import_transfer_candidate(std::span<const std::uint8_t>s,std::uint32_t begin,const std::map<std::uint32_t,std::pair<std::string,std::string>>&iat,const std::map<std::uint32_t,std::uint32_t>&thunks){if(s.empty())return true;for(std::size_t i=0;i<s.size();++i){const auto op=s[i];if((op==0xe8||op==0xe9)&&i+5<=s.size()){std::int32_t rel=0;std::memcpy(&rel,s.data()+i+1,4);auto t=std::int64_t(begin)+static_cast<std::int64_t>(i)+5+rel;if(t>=0&&t<=0xffffffffll&&thunks.count(static_cast<std::uint32_t>(t)))return true;}else if(op==0xeb&&i+2<=s.size()){auto rel=static_cast<std::int8_t>(s[i+1]);auto t=std::int64_t(begin)+static_cast<std::int64_t>(i)+2+rel;if(t>=0&&t<=0xffffffffll&&thunks.count(static_cast<std::uint32_t>(t)))return true;}else if(op==0xff&&i+2<=s.size()){const auto m=s[i+1];if((m&0xf8)==0xd0)return true;if((m==0x15||m==0x25)&&i+6<=s.size()){std::int32_t rel=0;std::memcpy(&rel,s.data()+i+2,4);auto t=std::int64_t(begin)+static_cast<std::int64_t>(i)+6+rel;if(t>=0&&t<=0xffffffffll&&iat.count(static_cast<std::uint32_t>(t)))return true;}}}return false;}
bool interesting_api(std::string_view n){static constexpr std::array<std::string_view,35>a={"IsDebuggerPresent","CheckRemoteDebuggerPresent","NtQueryInformationProcess","ZwQueryInformationProcess","NtSetInformationThread","ZwSetInformationThread","NtQuerySystemInformation","ZwQuerySystemInformation","NtQueryObject","ZwQueryObject","NtYieldExecution","NtCreateThreadEx","GetThreadContext","Wow64GetThreadContext","NtGetContextThread","DebugBreak","RaiseException","CloseHandle","AddVectoredExceptionHandler","SetUnhandledExceptionFilter","OutputDebugStringA","OutputDebugStringW","QueryPerformanceCounter","GetTickCount","GetTickCount64","timeGetTime","FindWindowA","FindWindowW","EnumWindows","CreateToolhelp32Snapshot","Process32FirstA","Process32FirstW","GetProcAddress","lstrcmpW","lstrcmpiW"};return std::find(a.begin(),a.end(),n)!=a.end()||n=="Process32NextA"||n=="Process32NextW"||n=="EnumProcesses";}
std::vector<ImportedCall> find_import_calls(std::span<const std::uint8_t>d,const PeInfo&pe){
    std::vector<ImportedCall>out;if(!pe.valid||!pe.pe64)return out;
    std::map<std::uint32_t,std::pair<std::string,std::string>>iat;constexpr std::uint32_t w=8;for(const auto&m:pe.imports)for(std::size_t i=0;i<m.functions.size();++i){const auto&f=m.functions[i];if(!f.by_ordinal&&interesting_api(f.name))iat[m.iat_rva+static_cast<std::uint32_t>(i)*w]={m.name,f.name};}if(iat.empty())return out;
    std::map<std::uint32_t,std::uint32_t>thunk_to_iat;
    for(const auto&s:pe.sections){if(!(s.characteristics&0x20000000u)||!s.raw_size||std::uint64_t(s.raw_offset)+s.raw_size>d.size())continue;for(std::size_t q=0;q+6<=s.raw_size;++q){auto o=std::size_t(s.raw_offset)+q;if(d[o]!=0xff||d[o+1]!=0x25)continue;std::int32_t disp=0;std::memcpy(&disp,d.data()+o+2,4);auto t=std::int64_t(s.rva+q+6)+disp;if(t>=0&&t<=0xffffffffll&&iat.count(static_cast<std::uint32_t>(t)))thunk_to_iat[s.rva+static_cast<std::uint32_t>(q)]=static_cast<std::uint32_t>(t);}}
    std::set<std::uint32_t>seen;
    auto emit=[&](std::uint32_t cr,std::uint32_t ir,std::string transfer){auto f=runtime_func(pe,cr);if(!f.end||!seen.insert(cr).second)return;auto nm=iat.find(ir);if(nm==iat.end())return;out.push_back({nm->second.first,nm->second.second,std::move(transfer),cr,f.begin,f.end,ir});};
    auto volatile_reg=[](ZydisRegister r){r=large(r);return r==ZYDIS_REGISTER_RAX||r==ZYDIS_REGISTER_RCX||r==ZYDIS_REGISTER_RDX||r==ZYDIS_REGISTER_R8||r==ZYDIS_REGISTER_R9||r==ZYDIS_REGISTER_R10||r==ZYDIS_REGISTER_R11;};
    // Normalize direct IAT calls, relative calls through import thunks, tail-jumps and register-indirect IAT calls.
    for(const auto&rf:pe.exception.runtime_functions){
        if(!import_transfer_candidate(raw_runtime_function(d,pe,rf),rf.begin_rva,iat,thunk_to_iat))continue;
        auto ins=decode_range(d,pe,{rf.begin_rva,rf.end_rva});std::map<ZydisRegister,std::uint32_t>alias;
        for(const auto&x:ins){
            bool emitted_call=false;
            if((x.zi.meta.category==ZYDIS_CATEGORY_CALL||x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR)&&x.zi.operand_count_visible>=1){
                const auto&q=x.ops[0];std::uint32_t ir=0;
                if(q.type==ZYDIS_OPERAND_TYPE_MEMORY&&q.mem.index==ZYDIS_REGISTER_NONE&&large(q.mem.base)==ZYDIS_REGISTER_RIP){auto disp=q.mem.disp.has_displacement?q.mem.disp.value:0;auto t=std::int64_t(x.rva+x.zi.length)+disp;if(t>=0&&t<=0xffffffffll&&iat.count(static_cast<std::uint32_t>(t)))ir=static_cast<std::uint32_t>(t);}
                else if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE&&q.imm.is_relative&&(x.zi.meta.category==ZYDIS_CATEGORY_CALL||x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR)){auto t=std::int64_t(x.rva+x.zi.length)+q.imm.value.s;if(t>=0&&t<=0xffffffffll){auto it=thunk_to_iat.find(static_cast<std::uint32_t>(t));if(it!=thunk_to_iat.end())ir=it->second;}}
                else if(q.type==ZYDIS_OPERAND_TYPE_REGISTER&&x.zi.meta.category==ZYDIS_CATEGORY_CALL){auto it=alias.find(large(q.reg.value));if(it!=alias.end())ir=it->second;}
                if(ir){std::string transfer;if(q.type==ZYDIS_OPERAND_TYPE_REGISTER)transfer="call_iat_register";else if(x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR&&q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE)transfer="tail_jmp_thunk";else if(x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR)transfer="tail_jmp_iat";else if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE)transfer="call_thunk";else transfer="call_iat";emit(x.rva,ir,std::move(transfer));emitted_call=x.zi.meta.category==ZYDIS_CATEGORY_CALL;}
            }
            if(x.zi.operand_count_visible&&x.ops[0].type==ZYDIS_OPERAND_TYPE_REGISTER&&(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)){
                auto dst=large(x.ops[0].reg.value);std::optional<std::uint32_t>v;
                if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2){const auto&q=x.ops[1];if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){auto it=alias.find(large(q.reg.value));if(it!=alias.end())v=it->second;}else if(q.type==ZYDIS_OPERAND_TYPE_MEMORY&&q.mem.index==ZYDIS_REGISTER_NONE&&large(q.mem.base)==ZYDIS_REGISTER_RIP){auto disp=q.mem.disp.has_displacement?q.mem.disp.value:0;auto t=std::int64_t(x.rva+x.zi.length)+disp;if(t>=0&&t<=0xffffffffll&&iat.count(static_cast<std::uint32_t>(t)))v=static_cast<std::uint32_t>(t);}}
                if(v)alias[dst]=*v;else alias.erase(dst);
            }
            if(emitted_call){for(auto it=alias.begin();it!=alias.end();){if(volatile_reg(it->first))it=alias.erase(it);else ++it;}}
        }
    }
    std::sort(out.begin(),out.end(),[](const auto&a,const auto&b){return a.callsite<b.callsite;});return out;
}
std::optional<std::uint64_t> scalar_arg(std::span<const std::uint8_t>d,const PeInfo&pe,const ImportedCall&c,int arg){if(arg<0||arg>3||!c.func_end)return{};auto ins=decode_range(d,pe,{c.func_begin,c.func_end});if(ins.empty())return{};auto want=std::array<ZydisRegister,4>{ZYDIS_REGISTER_RCX,ZYDIS_REGISTER_RDX,ZYDIS_REGISTER_R8,ZYDIS_REGISTER_R9}[arg];auto cur=large(want);std::size_t idx=ins.size();for(std::size_t i=0;i<ins.size();++i)if(ins[i].rva==c.callsite){idx=i;break;}if(idx==ins.size())return{};std::size_t seen=0;for(std::size_t z=idx;z-->0&&seen<96;){const auto&x=ins[z];++seen;if(!x.zi.operand_count_visible||x.ops[0].type!=ZYDIS_OPERAND_TYPE_REGISTER||large(x.ops[0].reg.value)!=cur||(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)==0)continue;if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2){const auto&q=x.ops[1];if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){cur=large(q.reg.value);continue;}if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE){auto v=q.imm.value.u;if(x.ops[0].size==64&&q.size==32)v=static_cast<std::uint64_t>(static_cast<std::int64_t>(static_cast<std::int32_t>(v)));return v;}}if(x.zi.mnemonic==ZYDIS_MNEMONIC_XOR&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER&&large(x.ops[1].reg.value)==cur)return 0;return{};}return{};}
struct PointerArg{std::string source;std::uint32_t rva=0;};
std::optional<PointerArg> pointer_rva_arg(std::span<const std::uint8_t>d,const PeInfo&pe,const ImportedCall&c,int arg){if(arg<0||arg>3||!c.func_end)return{};auto ins=decode_range(d,pe,{c.func_begin,c.func_end});if(ins.empty())return{};auto cur=large(std::array<ZydisRegister,4>{ZYDIS_REGISTER_RCX,ZYDIS_REGISTER_RDX,ZYDIS_REGISTER_R8,ZYDIS_REGISTER_R9}[arg]);std::size_t idx=ins.size();for(std::size_t i=0;i<ins.size();++i)if(ins[i].rva==c.callsite){idx=i;break;}if(idx==ins.size())return{};std::int64_t add=0;std::size_t seen=0;for(std::size_t z=idx;z-->0&&seen<128;){const auto&x=ins[z];++seen;if(!x.zi.operand_count_visible||x.ops[0].type!=ZYDIS_OPERAND_TYPE_REGISTER||large(x.ops[0].reg.value)!=cur||(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)==0)continue;if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2){const auto&q=x.ops[1];if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){cur=large(q.reg.value);continue;}if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE){auto va=q.imm.value.u;if(x.ops[0].size==64&&q.size==32)va=static_cast<std::uint64_t>(static_cast<std::int64_t>(static_cast<std::int32_t>(va)));auto sva=static_cast<std::int64_t>(va)+add;if(sva<0||static_cast<std::uint64_t>(sva)<pe.image_base||static_cast<std::uint64_t>(sva)-pe.image_base>0xffffffffull)return{};return PointerArg{"IMM_IMAGE_VA",static_cast<std::uint32_t>(static_cast<std::uint64_t>(sva)-pe.image_base)};}if(q.type==ZYDIS_OPERAND_TYPE_MEMORY&&q.mem.index==ZYDIS_REGISTER_NONE&&large(q.mem.base)==ZYDIS_REGISTER_RIP){auto disp=q.mem.disp.has_displacement?q.mem.disp.value:0;auto slot=std::int64_t(x.rva+x.zi.length)+disp;if(slot<0||slot>0xffffffffll)return{};auto so=rvaoff(pe,static_cast<std::uint32_t>(slot),d.size());if(!so||*so+8>d.size())return{};std::uint64_t va=0;std::memcpy(&va,d.data()+*so,8);auto sva=static_cast<std::int64_t>(va)+add;if(sva<0||static_cast<std::uint64_t>(sva)<pe.image_base||static_cast<std::uint64_t>(sva)-pe.image_base>0xffffffffull)return{};return PointerArg{"RIP_GLOBAL_PTR",static_cast<std::uint32_t>(static_cast<std::uint64_t>(sva)-pe.image_base)};}return{};}if(x.zi.mnemonic==ZYDIS_MNEMONIC_LEA&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_MEMORY){const auto&m=x.ops[1].mem;if(m.index!=ZYDIS_REGISTER_NONE)return{};auto disp=m.disp.has_displacement?m.disp.value:0;if(large(m.base)==ZYDIS_REGISTER_RIP){auto r=std::int64_t(x.rva+x.zi.length)+disp+add;if(r<0||r>0xffffffffll)return{};return PointerArg{"RIP_GLOBAL",static_cast<std::uint32_t>(r)};}if(m.base!=ZYDIS_REGISTER_NONE){cur=large(m.base);add+=disp;continue;}return{};}if((x.zi.mnemonic==ZYDIS_MNEMONIC_ADD||x.zi.mnemonic==ZYDIS_MNEMONIC_SUB)&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_IMMEDIATE){auto v=x.ops[1].imm.value.s;add+=x.zi.mnemonic==ZYDIS_MNEMONIC_ADD?v:-v;continue;}return{};}return{};}
struct AsciiArg{std::string value,source;std::uint32_t rva=0;std::uint64_t offset=0;};
std::optional<AsciiArg> ascii_at_rva(std::span<const std::uint8_t>d,const PeInfo&pe,std::uint32_t rva,std::string source){auto o=rvaoff(pe,rva,d.size());if(!o)return{};std::string v;v.reserve(64);for(std::size_t i=0;i<128&&*o+i<d.size();++i){auto b=d[*o+i];if(!b){if(v.empty())return{};return AsciiArg{std::move(v),std::move(source),rva,*o};}if(b<0x20||b>0x7e)return{};v.push_back(static_cast<char>(b));}return{};}
std::optional<AsciiArg> pointer_ascii_arg(std::span<const std::uint8_t>d,const PeInfo&pe,const ImportedCall&c,int arg){auto p=pointer_rva_arg(d,pe,c,arg);if(!p)return{};return ascii_at_rva(d,pe,p->rva,p->source);}
struct Utf16Arg{std::string value,source;std::uint32_t rva=0;std::uint64_t offset=0;};
std::optional<Utf16Arg> utf16_ascii_at_rva(std::span<const std::uint8_t>d,const PeInfo&pe,std::uint32_t rva,std::string source){auto o=rvaoff(pe,rva,d.size());if(!o)return{};std::string v;v.reserve(64);for(std::size_t i=0;i<128&&*o+2*i+1<d.size();++i){auto lo=d[*o+2*i],hi=d[*o+2*i+1];if(!lo&&!hi){if(v.empty())return{};return Utf16Arg{std::move(v),std::move(source),rva,*o};}if(hi||lo<0x20||lo>0x7e)return{};v.push_back(static_cast<char>(lo));}return{};}
std::optional<Utf16Arg> pointer_utf16_ascii_arg(std::span<const std::uint8_t>d,const PeInfo&pe,const ImportedCall&c,int arg){auto p=pointer_rva_arg(d,pe,c,arg);if(!p)return{};return utf16_ascii_at_rva(d,pe,p->rva,p->source);}

std::optional<std::uint64_t> stack_scalar_arg(std::span<const std::uint8_t>d,const PeInfo&pe,const ImportedCall&c,int arg){if(arg<4||!c.func_end)return{};auto ins=decode_range(d,pe,{c.func_begin,c.func_end});std::size_t idx=ins.size();for(std::size_t i=0;i<ins.size();++i)if(ins[i].rva==c.callsite){idx=i;break;}if(idx==ins.size())return{};const auto target=std::int64_t(0x20+8*(arg-4));std::map<ZydisRegister,std::uint64_t>regs;std::size_t seen=0;for(std::size_t z=idx;z-->0&&seen<160;){const auto&x=ins[z];++seen;if(x.zi.meta.category==ZYDIS_CATEGORY_CALL)break;if(x.zi.operand_count_visible>=1&&x.ops[0].type==ZYDIS_OPERAND_TYPE_MEMORY&&(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)&&x.ops[0].mem.index==ZYDIS_REGISTER_NONE&&large(x.ops[0].mem.base)==ZYDIS_REGISTER_RSP&&(x.ops[0].mem.disp.has_displacement?x.ops[0].mem.disp.value:0)==target){if(x.zi.mnemonic!=ZYDIS_MNEMONIC_MOV||x.zi.operand_count_visible<2)return{};const auto&q=x.ops[1];if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE)return q.imm.value.u;if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){auto it=regs.find(large(q.reg.value));if(it!=regs.end())return it->second;}return{};}if(x.zi.operand_count_visible&&x.ops[0].type==ZYDIS_OPERAND_TYPE_REGISTER&&(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)){auto dst=large(x.ops[0].reg.value);std::optional<std::uint64_t>v;if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2){const auto&q=x.ops[1];if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE)v=q.imm.value.u;else if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){auto it=regs.find(large(q.reg.value));if(it!=regs.end())v=it->second;}}else if(x.zi.mnemonic==ZYDIS_MNEMONIC_XOR&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER&&large(x.ops[1].reg.value)==dst)v=0;if(v)regs[dst]=*v;else regs.erase(dst);}}return{};}
bool postcall_return_compare_branch(std::span<const std::uint8_t>d,const PeInfo&pe,const ImportedCall&c,std::uint64_t value,std::uint32_t&cmp_rva,std::uint32_t&branch_rva){if(!c.func_end)return false;auto ins=decode_range(d,pe,{c.func_begin,c.func_end});std::size_t idx=ins.size();for(std::size_t i=0;i<ins.size();++i)if(ins[i].rva==c.callsite){idx=i;break;}if(idx==ins.size())return false;for(std::size_t i=idx+1;i<ins.size()&&i<=idx+8;++i){const auto&x=ins[i];if(x.zi.meta.category==ZYDIS_CATEGORY_CALL||x.zi.meta.category==ZYDIS_CATEGORY_RET)return false;if(x.zi.mnemonic==ZYDIS_MNEMONIC_CMP&&x.zi.operand_count_visible>=2){bool ret=false;std::optional<std::uint64_t>imm;for(std::uint8_t k=0;k<x.zi.operand_count_visible;++k){if(x.ops[k].type==ZYDIS_OPERAND_TYPE_REGISTER&&large(x.ops[k].reg.value)==ZYDIS_REGISTER_RAX)ret=true;if(x.ops[k].type==ZYDIS_OPERAND_TYPE_IMMEDIATE&&!x.ops[k].imm.is_relative)imm=x.ops[k].imm.value.u;}if(ret&&imm&&static_cast<std::uint32_t>(*imm)==static_cast<std::uint32_t>(value)){cmp_rva=x.rva;for(std::size_t j=i+1;j<ins.size()&&j<=i+3;++j)if(ins[j].zi.meta.category==ZYDIS_CATEGORY_COND_BR){branch_rva=ins[j].rva;return true;}return false;}}}return false;}
struct StackArg{ZydisRegister base=ZYDIS_REGISTER_NONE;std::int64_t disp=0;};
