std::optional<std::string> canonical_debugger_name(std::string_view in){static constexpr std::array<std::string_view,10>names={"x64dbg","x32dbg","ollydbg","windbg","immunity debugger","cheat engine","process hacker","ida64","idaq","ghidra"};std::string x;for(unsigned char c:in)x.push_back(static_cast<char>(std::tolower(c)));for(auto n:names)if(x==n)return std::string(n);return{};}
struct NameHit{std::uint64_t off=0;std::string name;};
std::vector<NameHit> debugger_name_hits(std::span<const std::uint8_t>d){static constexpr std::array<std::string_view,10>names={"x64dbg","x32dbg","ollydbg","windbg","immunity debugger","cheat engine","process hacker","ida64","idaq","ghidra"};std::array<std::optional<std::size_t>,10>a{},w{};std::size_t left=20;auto test=[&](std::size_t i,std::size_t n){auto s=names[n];if(!a[n]&&i+s.size()<=d.size()){bool ok=true;for(std::size_t k=1;k<s.size();++k){auto c=d[i+k];if(c>='A'&&c<='Z')c=std::uint8_t(c+32);if(c!=static_cast<std::uint8_t>(s[k])){ok=false;break;}}if(ok){a[n]=i;--left;}}if(!w[n]&&i+2*s.size()<=d.size()){bool ok=true;for(std::size_t k=0;k<s.size();++k){auto c=d[i+2*k];if(c>='A'&&c<='Z')c=std::uint8_t(c+32);if(d[i+2*k+1]!=0||c!=static_cast<std::uint8_t>(s[k])){ok=false;break;}}if(ok){w[n]=i;--left;}}};for(std::size_t i=0;i<d.size()&&left;++i){auto c=d[i];if(c>='A'&&c<='Z')c=std::uint8_t(c+32);switch(c){case 'x':test(i,0);test(i,1);break;case 'o':test(i,2);break;case 'w':test(i,3);break;case 'i':test(i,4);test(i,7);test(i,8);break;case 'c':test(i,5);break;case 'p':test(i,6);break;case 'g':test(i,9);break;default:break;}}std::vector<NameHit>out;for(std::size_t n=0;n<names.size();++n){if(a[n])out.push_back({*a[n],std::string(names[n])});if(w[n])out.push_back({*w[n],std::string(names[n])+" (UTF-16LE)"});}return out;}
struct ExecFileRange{std::uint32_t rva=0;std::uint64_t file_offset=0,size=0;std::string section;};
std::optional<ExecFileRange> executable_file_range(const PeInfo&pe,std::uint32_t rva,std::uint64_t size){if(!size||size>(1ull<<20))return{};for(const auto&s:pe.sections){if(!(s.characteristics&0x20000000u)||!s.raw_size)continue;if(rva<s.rva)continue;auto delta=std::uint64_t(rva)-s.rva;if(delta>s.raw_size||size>std::uint64_t(s.raw_size)-delta)continue;return ExecFileRange{rva,std::uint64_t(s.raw_offset)+delta,size,s.name};}return{};}
std::optional<std::uint32_t> rip_pointer_origin(const std::vector<Decoded>&ins,std::size_t before,ZydisRegister reg){auto cur=large(reg);std::size_t seen=0;for(std::size_t z=before;z-->0&&seen<48;){const auto&x=ins[z];++seen;if(!x.zi.operand_count_visible||x.ops[0].type!=ZYDIS_OPERAND_TYPE_REGISTER||large(x.ops[0].reg.value)!=cur||(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)==0)continue;if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER){cur=large(x.ops[1].reg.value);continue;}if(x.zi.mnemonic==ZYDIS_MNEMONIC_LEA&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_MEMORY){const auto&m=x.ops[1].mem;if(m.index==ZYDIS_REGISTER_NONE&&large(m.base)==ZYDIS_REGISTER_RIP){auto disp=m.disp.has_displacement?m.disp.value:0;auto target=std::int64_t(x.rva+x.zi.length)+disp;if(target>=0&&target<=0xffffffffll)return static_cast<std::uint32_t>(target);}return{};}return{};}return{};}
bool register_zeroed_before(const std::vector<Decoded>&ins,std::size_t before,ZydisRegister reg){auto cur=large(reg);std::size_t seen=0;for(std::size_t z=before;z-->0&&seen<48;){const auto&x=ins[z];++seen;if(!x.zi.operand_count_visible||x.ops[0].type!=ZYDIS_OPERAND_TYPE_REGISTER||large(x.ops[0].reg.value)!=cur||(x.ops[0].actions&ZYDIS_OPERAND_ACTION_WRITE)==0)continue;if(x.zi.mnemonic==ZYDIS_MNEMONIC_MOV&&x.zi.operand_count_visible>=2){const auto&q=x.ops[1];if(q.type==ZYDIS_OPERAND_TYPE_REGISTER){cur=large(q.reg.value);continue;}if(q.type==ZYDIS_OPERAND_TYPE_IMMEDIATE)return q.imm.value.u==0;}if(x.zi.mnemonic==ZYDIS_MNEMONIC_XOR&&x.zi.operand_count_visible>=2&&x.ops[1].type==ZYDIS_OPERAND_TYPE_REGISTER&&large(x.ops[1].reg.value)==cur)return true;return false;}return false;}
