LocalCfg bounded_local_cfg(std::span<const std::uint8_t>d,const PeInfo&pe,FuncRange f){LocalCfg g;if(!f.end||f.end<=f.begin||f.end-f.begin>(1u<<20))return g;g.ins=decode_range(d,pe,f);if(g.ins.empty()||g.ins.back().rva+g.ins.back().zi.length!=f.end){g.ins.clear();return g;}g.edges.resize(g.ins.size());for(std::size_t i=0;i<g.ins.size();++i)g.by_rva[g.ins[i].rva]=i;auto edge=[&](std::size_t a,std::uint32_t r){auto it=g.by_rva.find(r);if(it!=g.by_rva.end()&&std::find(g.edges[a].begin(),g.edges[a].end(),it->second)==g.edges[a].end())g.edges[a].push_back(it->second);};for(std::size_t i=0;i<g.ins.size();++i){const auto&x=g.ins[i];std::optional<std::uint32_t>fall;if(i+1<g.ins.size())fall=g.ins[i+1].rva;if(x.zi.meta.category==ZYDIS_CATEGORY_RET)continue;if(x.zi.meta.category==ZYDIS_CATEGORY_UNCOND_BR){if(auto t=relative_control_target(x))edge(i,*t);continue;}if(x.zi.meta.category==ZYDIS_CATEGORY_COND_BR){if(auto t=relative_control_target(x))edge(i,*t);if(fall)edge(i,*fall);continue;}if(fall)edge(i,*fall);}return g;}
