bool cfg_dominates(const LocalCfg&g,std::size_t dom,std::size_t node){if(g.ins.empty()||dom>=g.ins.size()||node>=g.ins.size()||!cfg_reachable(g,0,node))return false;if(dom==0)return true;return !cfg_reachable(g,0,node,dom);}
std::optional<std::uint32_t> conditional_trap_controller(const LocalCfg&g,std::size_t trap){for(std::size_t i=0;i<g.ins.size();++i){if(g.ins[i].zi.meta.category!=ZYDIS_CATEGORY_COND_BR||g.edges[i].size()!=2||!cfg_dominates(g,i,trap))continue;const bool a=cfg_reachable(g,g.edges[i][0],trap),b=cfg_reachable(g,g.edges[i][1],trap);if(a!=b)return g.ins[i].rva;}return{};}
